import type { Page } from '@playwright/test';

// 訂單編號在餐廳後台顯示為四位數（#0001），外送員工作台顯示為 #1
const restaurantOrderLabel = (orderId: number) => `#${String(orderId).padStart(4, '0')}`;

export const restaurantSignInLocators = (page: Page) => ({
  username: page.getByTestId('sign-in-username'),
  password: page.getByTestId('sign-in-password'),
  submit: page.getByTestId('sign-in-submit'),
});

export const restaurantOrdersLocators = (page: Page) => {
  const row = (orderId: number) =>
    page.getByTestId('order-row').filter({ has: page.getByText(restaurantOrderLabel(orderId), { exact: true }) });
  return {
    heading: page.getByRole('heading', { name: '訂單管理', level: 1 }),
    table: page.getByTestId('order-table'),
    refresh: page.getByRole('button', { name: /重新整理/ }),
    row,
    status: (orderId: number) => row(orderId).getByTestId('order-status'),
    readyButton: (orderId: number) => row(orderId).getByTestId('order-ready-button'),
  };
};

export const driverAccountLocators = (page: Page) => ({
  continueAsDriver: page.getByTestId('continue-as-driver'),
});

export const driverDeliveryLocators = (page: Page) => ({
  navDelivery: page.getByTestId('nav-driver-delivery'),
  activeCard: page.getByTestId('active-delivery-card'),
  orderLabel: (orderId: number) => page.getByTestId('active-delivery-card').getByText(`訂單 #${orderId}`),
  completeDelivery: page.getByTestId('complete-delivery'),
  noActiveDelivery: page.getByTestId('no-active-delivery'),
});

import type { Page } from '@playwright/test';
import {
  driverAccountLocators,
  driverDeliveryLocators,
  restaurantOrdersLocators,
  restaurantSignInLocators,
} from './locators';

export const restaurantSignInActions = (page: Page) => {
  const locators = restaurantSignInLocators(page);
  return {
    open: () => page.goto('/management/sign-in'),
    signIn: async (login: { username: string; password: string }) => {
      await locators.username.fill(login.username);
      await locators.password.fill(login.password);
      await locators.submit.click();
    },
  };
};

export const restaurantOrdersActions = (page: Page) => {
  const locators = restaurantOrdersLocators(page);
  return {
    markReady: (orderId: number) => locators.readyButton(orderId).click(),
    refresh: () => locators.refresh.click(),
  };
};

export const driverActions = (page: Page) => {
  const account = driverAccountLocators(page);
  const delivery = driverDeliveryLocators(page);
  return {
    enterWorkbench: async () => {
      await page.goto('/account');
      await account.continueAsDriver.click();
    },
    openActiveDelivery: () => delivery.navDelivery.click(),
    completeDelivery: () => delivery.completeDelivery.click(),
    // 等外送員畫面顯示完成，餐廳端才重新查詢（這裡只等待，不做驗收）
    waitUntilNoActiveDelivery: () => delivery.noActiveDelivery.waitFor(),
  };
};

import type { Page } from '@playwright/test';
import { restaurantSignInActions } from '../pages/actions';
import { expect, test as demoTest } from './demo';

export const test = demoTest.extend<{ restaurantPage: Page; driverPage: Page }>({
  // 共用登入準備：餐廳管理者已登入訂單管理頁面
  restaurantPage: async ({ page, demo }, use) => {
    const signIn = restaurantSignInActions(page);
    await signIn.open();
    await signIn.signIn(demo.restaurant_login);
    await page.waitForURL('**/management/orders');
    await use(page);
  },

  // 獨立的外送員瀏覽器環境；測試成功或失敗都會關閉
  driverPage: async ({ browser }, use) => {
    const context = await browser.newContext({ baseURL: 'http://localhost:8082' });
    try {
      await use(await context.newPage());
    } finally {
      await context.close();
    }
  },
});

export { expect };

