    await expect(orders.readyButton(orderId)).toBeVisible();

    // Act: 2. 按下該筆訂單的「備餐完成」。
    await actions.markReady(orderId);

    // Assert
    await expect(orders.status(orderId)).toHaveText('待取餐');
    await expect(orders.readyButton(orderId)).toHaveCount(0);
  });
});

